#!/usr/bin/env bash
# Records the T0 count of every item of experiments/baseline-coverage-checklist.md with READ-ONLY queries
# (SELECT only; run against the quiescent preserved baseline, never modifies it) and the engine facts.
# usage: coverage_counts.sh <mariadb-container> <root-password>  -> TSV on stdout: area<TAB>item<TAB>count-or-value
C=$1; PW=$2
q() { docker exec -e MYSQL_PWD="$PW" "$C" mysql -uroot -N -B -e "$2" 2>/dev/null | tr '\n' ';' | sed 's/;$//'; }
row() { printf '%s\t%s\t%s\n' "$1" "$2" "$(q x "$3")"; }
echo "# T0 baseline coverage counts, read-only SELECTs, $(date -u +%FT%TZ)"
row cinder "volumes available" "SELECT COUNT(*) FROM cinder.volumes WHERE deleted=0 AND status='available'"
row cinder "volumes in-use" "SELECT COUNT(*) FROM cinder.volumes WHERE deleted=0 AND status='in-use'"
row cinder "volumes error" "SELECT COUNT(*) FROM cinder.volumes WHERE deleted=0 AND status='error'"
row cinder "volumes deleted (soft)" "SELECT COUNT(*) FROM cinder.volumes WHERE deleted=1"
row cinder "snapshots" "SELECT COUNT(*) FROM cinder.snapshots WHERE deleted=0"
row cinder "volume_admin_metadata temporary='True'" "SELECT COUNT(*) FROM cinder.volume_admin_metadata WHERE \`key\`='temporary' AND value='True' AND deleted=0"
row cinder "volumes migration_status LIKE 'target:%' (incl. deleted)" "SELECT COUNT(*) FROM cinder.volumes WHERE migration_status LIKE 'target:%'"
row cinder "volumes migration_status (distinct, count)" "SELECT CONCAT(IFNULL(migration_status,'NULL'),'=',COUNT(*)) FROM cinder.volumes GROUP BY migration_status"
row cinder "quota_usages rows" "SELECT COUNT(*) FROM cinder.quota_usages WHERE deleted=0"
row cinder "quotas rows (project quotas set)" "SELECT CONCAT(resource,'=',hard_limit) FROM cinder.quotas WHERE deleted=0 ORDER BY resource"
row cinder "consistencygroup/group quota rows" "SELECT COUNT(*) FROM cinder.quotas WHERE deleted=0 AND resource IN ('consistencygroups','groups')"
row cinder "quota_usages for groups/consistencygroups" "SELECT COUNT(*) FROM cinder.quota_usages WHERE deleted=0 AND resource IN ('consistencygroups','groups')"
row nova "instances by vm_state (deleted=0)" "SELECT CONCAT(vm_state,'=',COUNT(*)) FROM nova.instances WHERE deleted=0 GROUP BY vm_state"
row nova "instances ERROR without host" "SELECT COUNT(*) FROM nova.instances WHERE deleted=0 AND vm_state='error' AND host IS NULL"
row nova "instances soft-deleted (vm_state soft-delete)" "SELECT COUNT(*) FROM nova.instances WHERE vm_state='soft-delete'"
row nova "instances deleted<>0 (live table)" "SELECT COUNT(*) FROM nova.instances WHERE deleted<>0"
row nova "shadow_instances (archived)" "SELECT COUNT(*) FROM nova.shadow_instances"
row nova "instances per host" "SELECT CONCAT(IFNULL(host,'NULL'),'=',COUNT(*)) FROM nova.instances WHERE deleted=0 GROUP BY host"
row nova "compute_nodes rows" "SELECT CONCAT(host,'/',hypervisor_hostname,' deleted=',deleted) FROM nova.compute_nodes"
row nova "flavors with hw:numa_nodes" "SELECT COUNT(*) FROM nova_api.flavor_extra_specs WHERE \`key\`='hw:numa_nodes'"
row nova "flavors with hw:cpu_policy=dedicated" "SELECT COUNT(*) FROM nova_api.flavor_extra_specs WHERE \`key\`='hw:cpu_policy' AND value='dedicated'"
row nova "instances with numa_topology" "SELECT COUNT(*) FROM nova.instance_extra WHERE numa_topology IS NOT NULL"
row nova "block_device_mapping volume-backed (source_type=volume)" "SELECT COUNT(*) FROM nova.block_device_mapping WHERE deleted=0 AND source_type='volume'"
row nova "migrations rows by status" "SELECT CONCAT(migration_type,'/',status,'=',COUNT(*)) FROM nova.migrations GROUP BY migration_type,status"
row nova "instance_extra with migration_context" "SELECT COUNT(*) FROM nova.instance_extra WHERE migration_context IS NOT NULL"
row nova "request_specs" "SELECT COUNT(*) FROM nova_api.request_specs"
row nova "request_specs with scheduler hints (spec like %scheduler_hints%group%)" "SELECT COUNT(*) FROM nova_api.request_specs WHERE spec LIKE '%group%'"
row nova "instance_groups" "SELECT COUNT(*) FROM nova_api.instance_groups"
row nova "instance_actions" "SELECT COUNT(*) FROM nova.instance_actions"
row nova "quotas (api db)" "SELECT COUNT(*) FROM nova_api.quotas"
row nova "quotas (legacy cell db, table nova.quotas)" "SELECT COUNT(*) FROM nova.quotas"
row nova "services (binary/host/version)" "SELECT CONCAT(\`binary\`,'/',host,' version=',version,' forced_down=',forced_down) FROM nova.services WHERE deleted=0"
row nova "host_mappings" "SELECT COUNT(*) FROM nova_api.host_mappings"
row nova "aggregates" "SELECT COUNT(*) FROM nova_api.aggregates"
row keystone "trusts" "SELECT COUNT(*) FROM keystone.trust"
row keystone "application credentials" "SELECT COUNT(*) FROM keystone.application_credential"
row keystone "credentials by type" "SELECT CONCAT(type,'=',COUNT(*)) FROM keystone.credential GROUP BY type"
row keystone "revocation_event rows" "SELECT COUNT(*) FROM keystone.revocation_event"
row keystone "federated: identity_provider/mapping/protocol" "SELECT CONCAT((SELECT COUNT(*) FROM keystone.identity_provider),'/',(SELECT COUNT(*) FROM keystone.mapping),'/',(SELECT COUNT(*) FROM keystone.federation_protocol))"
row keystone "password hasher per user (prefix of password_hash)" "SELECT CONCAT(l.name,':',SUBSTRING_INDEX(SUBSTRING(p.password_hash,1,7),'\$',2)) FROM keystone.password p JOIN keystone.local_user l ON l.id=p.local_user_id ORDER BY l.name"
row keystone "migrate_version" "SELECT CONCAT(repository_id,'=',version) FROM keystone.migrate_version"
row neutron "multi-segment networks (>1 segment)" "SELECT COUNT(*) FROM (SELECT network_id FROM neutron.networksegments GROUP BY network_id HAVING COUNT(*)>1) t"
row neutron "network_segment_ranges (type/physnet NULL?)" "SELECT CONCAT(network_type,'/',IFNULL(physical_network,'NULL'),'/',minimum,'-',maximum) FROM neutron.network_segment_ranges"
row neutron "quotas rows" "SELECT COUNT(*) FROM neutron.quotas"
row neutron "ports with binding profile <> ''" "SELECT COUNT(*) FROM neutron.ml2_port_bindings WHERE profile<>'' AND profile<>'{}'"
row neutron "extradhcpopts rows" "SELECT COUNT(*) FROM neutron.extradhcpopts"
row neutron "HA routers (routers with ha flag)" "SELECT COUNT(*) FROM neutron.router_extra_attributes WHERE ha=1"
row neutron "networkrbacs" "SELECT COUNT(*) FROM neutron.networkrbacs"
row neutron "standardattributes tags (tags table)" "SELECT COUNT(*) FROM neutron.tags"
row neutron "agents (type/host)" "SELECT CONCAT(agent_type,'/',host) FROM neutron.agents"
row glance "images with >1 location" "SELECT COUNT(*) FROM (SELECT image_id FROM glance.image_locations WHERE deleted=0 GROUP BY image_id HAVING COUNT(*)>1) t"
row glance "image_locations total" "SELECT COUNT(*) FROM glance.image_locations WHERE deleted=0"
row glance "image_locations.meta_data without \"backend\":" "SELECT COUNT(*) FROM glance.image_locations WHERE deleted=0 AND (meta_data IS NULL OR meta_data NOT LIKE '%\"backend\":%')"
row glance "tasks" "SELECT CONCAT(type,'/',status,'=',COUNT(*)) FROM glance.tasks GROUP BY type,status"
row placement "resource_providers (name parent?)" "SELECT CONCAT(name,IF(parent_provider_id IS NULL,'',' [nested]')) FROM placement.resource_providers"
row placement "nested providers" "SELECT COUNT(*) FROM placement.resource_providers WHERE parent_provider_id IS NOT NULL"
row placement "custom traits" "SELECT name FROM placement.traits WHERE name LIKE 'CUSTOM_%'"
row placement "consumers" "SELECT COUNT(*) FROM placement.consumers"
row placement "consumer_types table exists (1/0)" "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='placement' AND table_name='consumer_types'"
row placement "consumers without consumer_types row (no table in Ussuri: all)" "SELECT COUNT(*) FROM placement.consumers"
row placement "allocations: distinct consumers" "SELECT COUNT(DISTINCT consumer_id) FROM placement.allocations"
row placement "instances alive (nova) without allocation" "SELECT COUNT(*) FROM nova.instances i WHERE i.deleted=0 AND i.host IS NOT NULL AND i.uuid NOT IN (SELECT c.uuid FROM placement.consumers c JOIN placement.allocations a ON a.consumer_id=c.id)"
row engine "@@GLOBAL.sql_mode" "SELECT @@GLOBAL.sql_mode"
row engine "@@GLOBAL.version" "SELECT @@GLOBAL.version"
row engine "oslo.db session sql_mode used by the services/tools" "SELECT 'TRADITIONAL (oslo.db [database]mysql_sql_mode default; see report)'"
row engine "character_set_server / collation_server" "SELECT CONCAT(@@character_set_server,'/',@@collation_server)"
